mapper.select:
SELECT ticket.*, seller.username AS seller_username FROM ticket JOIN user seller ON seller.id = ticket.seller_id
ticket.seller_id = #{sellerId}
AND ticket.status = 'active' AND EXISTS ( SELECT 1 FROM auction a WHERE a.ticket_id = ticket.id AND a.status = 'ongoing' AND a.end_time <= CURRENT_TIMESTAMP )
AND ticket.status = 'active' AND EXISTS ( SELECT 1 FROM auction a WHERE a.ticket_id = ticket.id AND a.status = 'ongoing' AND a.end_time > CURRENT_TIMESTAMP )
AND ticket.status = #{status}
ORDER BY create_time DESC

mapper.insert:
INSERT INTO ticket_image (ticket_id, image_url, is_private, sort_order)
SELECT #{ticketId}, #{imageUrl}, #{isPrivate}, COALESCE(MAX(sort_order), -1) + 1
FROM ticket_image WHERE ticket_id = #{ticketId}
